  he: { dir: 'rtl', file: 'קובץ', edit: 'ערוך', view: 'תצוגה', profiles: 'פרופילים', newTab: 'כרטיסייה חדשה', newWindow: 'חלון חדש', incognito: 'חלון גלישה בסתר חדש', share: 'שתף', email: 'קישור אימייל', messages: 'הודעות', notes: 'הערות', print: 'הדפס...', undo: 'בטל', redo: 'בצע שוב', find: 'מצא', searchWeb: 'חפש באינטרנט', findItem: 'מצא...', findNext: 'מצא הבא', findPrevious: 'מצא הקודם', cut: 'גזור', copy: 'העתק', paste: 'הדבק', bookmarks: 'סרגל סימניות', urls: 'כתובות URL מלאות', reload: 'רענן', forceReload: 'רענן בכוח', fullscreen: 'החלף מסך מלא', sidebar: 'הסתר סרגל צד', editProfile: 'ערוך...', addProfile: 'הוסף פרופיל...' },
