} as const

export default function MenubarRtlExample() {
  let language = $state<keyof typeof translations>('ar')
  const t = translations[language]
  return (
    <div><select aria-label="Preview language" value={language} onChange={event => language = event.currentTarget.value as keyof typeof translations}><option value="ar">Arabic (العربية)</option><option value="he">Hebrew (עברית)</option><option value="en">English</option></select><Menubar class="w-72" dir={t.dir}><MenubarMenu><MenubarTrigger>{t.file}</MenubarTrigger><MenubarContent dir={t.dir}><MenubarItem>{t.newTab} <MenubarShortcut>⌘T</MenubarShortcut></MenubarItem><MenubarItem>{t.newWindow} <MenubarShortcut>⌘N</MenubarShortcut></MenubarItem><MenubarItem disabled>{t.incognito}</MenubarItem><MenubarSeparator /><MenubarSub><MenubarSubTrigger>{t.share}</MenubarSubTrigger><MenubarSubContent dir={t.dir}><MenubarItem>{t.email}</MenubarItem><MenubarItem>{t.messages}</MenubarItem><MenubarItem>{t.notes}</MenubarItem></MenubarSubContent></MenubarSub><MenubarSeparator /><MenubarItem>{t.print} <MenubarShortcut>⌘P</MenubarShortcut></MenubarItem></MenubarContent></MenubarMenu><MenubarMenu><MenubarTrigger>{t.edit}</MenubarTrigger><MenubarContent dir={t.dir}><MenubarItem>{t.undo} <MenubarShortcut>⌘Z</MenubarShortcut></MenubarItem><MenubarItem>{t.redo} <MenubarShortcut>⇧⌘Z</MenubarShortcut></MenubarItem><MenubarSeparator /><MenubarSub><MenubarSubTrigger>{t.find}</MenubarSubTrigger><MenubarSubContent dir={t.dir}><MenubarItem>{t.searchWeb}</MenubarItem><MenubarSeparator /><MenubarItem>{t.findItem}</MenubarItem><MenubarItem>{t.findNext}</MenubarItem><MenubarItem>{t.findPrevious}</MenubarItem></MenubarSubContent></MenubarSub><MenubarSeparator /><MenubarItem>{t.cut}</MenubarItem><MenubarItem>{t.copy}</MenubarItem><MenubarItem>{t.paste}</MenubarItem></MenubarContent></MenubarMenu><MenubarMenu><MenubarTrigger>{t.view}</MenubarTrigger><MenubarContent class="w-44" dir={t.dir}><MenubarCheckboxItem>{t.bookmarks}</MenubarCheckboxItem><MenubarCheckboxItem checked>{t.urls}</MenubarCheckboxItem><MenubarSeparator /><MenubarItem inset>{t.reload} <MenubarShortcut>⌘R</MenubarShortcut></MenubarItem><MenubarItem disabled inset>{t.forceReload} <MenubarShortcut>⇧⌘R</MenubarShortcut></MenubarItem><MenubarSeparator /><MenubarItem inset>{t.fullscreen}</MenubarItem><MenubarSeparator /><MenubarItem inset>{t.sidebar}</MenubarItem></MenubarContent></MenubarMenu><MenubarMenu><MenubarTrigger>{t.profiles}</MenubarTrigger><MenubarContent dir={t.dir}><MenubarRadioGroup value="benoit"><MenubarRadioItem value="andy">Andy</MenubarRadioItem><MenubarRadioItem value="benoit">Benoit</MenubarRadioItem><MenubarRadioItem value="luis">Luis</MenubarRadioItem></MenubarRadioGroup><MenubarSeparator /><MenubarItem inset>{t.editProfile}</MenubarItem><MenubarSeparator /><MenubarItem inset>{t.addProfile}</MenubarItem></MenubarContent></MenubarMenu></Menubar></div>
  )
}
